function placeModal(placeID=''){if(!canWrite())return;const p=state.places[placeID]||{id:id(),name:'',note:'',version:0};modal(p.version?'Изменить место':'Новое место хранения','Это может быть склад, помещение, стеллаж или полка.',`<form id="place-form" class="stack"><label class="field">Название<input class="input" name="name" required maxlength="100" value="${esc(p.name)}" placeholder="Склад А / Стеллаж 02 / Полка 3"></label><label class="field">Описание<textarea name="note" maxlength="200">${esc(p.note)}</textarea></label></form>`,formButtons('place-form'));$('#place-form').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;runForm(f,async()=>{const d=new FormData(f),place={...p,name:String(d.get('name')),note:String(d.get('note'))};const r=await send({id:id(),type:'place',place});toast(r.saved?'Место сохранено.':'Место ждёт подтверждения.',r.saved?'':'warn');});});}
function spaceModal(){if(state.me.role!=='owner')return;modal('Название и валюта','Смена валюты изменяет подпись, но не пересчитывает цены.',`<form id="space-form" class="stack"><label class="field">Название склада<input class="input" name="name" required maxlength="80" value="${esc(state.space.name)}"></label><label class="field">Валюта справочных цен<select name="currency">${[['RUB','Рубли · RUB'],['EUR','Евро · EUR'],['USD','Доллары · USD']].map(([v,t])=>`<option value="${v}" ${state.space.currency===v?'selected':''}>${t}</option>`).join('')}</select></label><div class="notice warn">Это не валютная конвертация. При смене валюты суммы в карточках останутся прежними.</div></form>`,formButtons('space-form'));$('#space-form').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;runForm(f,async()=>{const d=new FormData(f),space={name:String(d.get('name')),currency:String(d.get('currency'))};if(space.currency!==state.space.currency&&!confirm('Изменить обозначение валюты без пересчёта сумм?'))throw new Error('Изменение отменено.');const r=await send({id:id(),type:'space',space});toast(r.saved?'Настройки сохранены.':'Изменение ожидает подтверждения.');});});}
function operationModal(kind='in',itemID=''){
 if(!canWrite())return;if(!activeItems().length){newItemModal();toast('Сначала добавьте товар, затем оформите его приход.');return;}
 if(!['in','out','transfer','count'].includes(kind))kind='in';const initial=itemID||activeItems()[0].id;const firstPlace=placeFilter||Object.keys(state.places)[0];const secondPlace=Object.keys(state.places).find(x=>x!==firstPlace)||firstPlace;
 modal('Новое движение','Остаток изменится только после сохранения.',`<div class="form-tabs">${['in','out','transfer','count'].map(k=>`<button class="${kind===k?'active':''}" data-action="switch-operation" data-kind="${k}" data-id="${initial}">${names[k]}</button>`).join('')}</div><form id="operation-form" data-kind="${kind}"><div class="form-grid"><label class="field full">Товар<select name="itemId" id="op-item">${itemOptions(initial)}</select></label><label class="field ${kind==='transfer'?'':'full'}">${kind==='in'?'Куда поступает':kind==='count'?'Где пересчитываете':'Откуда забираете'}<select name="place" id="op-place">${placeOptions(firstPlace)}</select></label>${kind==='transfer'?`<label class="field">Куда перемещаете<select name="destination" id="op-destination">${placeOptions(secondPlace)}</select></label>`:''}<div class="quantity-preview" id="quantity-preview"></div><label class="field full">${kind==='count'?'Фактически посчитано':'Количество'}<input class="input" name="qty" id="op-qty" inputmode="decimal" required placeholder="0"><small id="qty-unit"></small></label><label class="field full">${kind==='count'?'Причина пересчёта — обязательно':'Комментарий'}<textarea name="note" maxlength="1000" ${kind==='count'?'required':''} placeholder="${kind==='count'?'Например, плановая инвентаризация':'Кому выдано, от кого получено, назначение'}"></textarea></label><label class="field full">Номер документа — необязательно<input class="input" name="ref" maxlength="100" placeholder="Накладная, заказ или внутренний номер"></label>${kind==='count'?'<div class="notice warn field full">Пересчёт задаёт фактический остаток в одном месте. При изменении остатка другим участником сервер потребует повторный пересчёт.</div>':''}</div></form>`,formButtons('operation-form',kind==='count'?'Зафиксировать факт':'Провести движение'));
 function preview(){const f=$('#operation-form');if(!f)return;const item=state.items[f.elements.itemId.value],p=f.elements.place.value,stock=state.stocks[D.key(item.id,p)]||{qty:0,version:0};f.dataset.expected=stock.version;$('#quantity-preview').innerHTML=`<span>Сейчас в этом месте</span><b>${q(stock.qty)} ${esc(item.unit)}</b>`;$('#qty-unit').textContent=`В ${item.unit}. Можно вводить до 3 знаков после запятой.`;}
 $('#op-item').addEventListener('change',preview);$('#op-place').addEventListener('change',preview);preview();upgradeOperation(kind);
 $('#operation-form').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;runForm(f,async()=>{const d=new FormData(f),p=String(d.get('place'));const c={id:id(),type:kind,itemId:String(d.get('itemId')),qty:D.decimal(d.get('qty')),note:String(d.get('note')),ref:String(d.get('ref')),expected:Number(f.dataset.expected)};
 if(kind==='in'||kind==='count')c.to=p;else c.from=p;if(kind==='transfer')c.to=String(d.get('destination'));
 // Fast local validation is a convenience, never a substitute for server authority.
 D.execute(state,c);const r=await send(c);toast(r.saved?'Движение проведено. Остатки обновлены.':'Черновик сохранён. Остатки пока не изменились.',r.saved?'':'warn');});});
}
function detailModal(itemID){const x=state.items[itemID];if(!x)return;const rows=Object.values(state.places).map(p=>({p,n:itemTotal(x,p.id)}));modal('Карточка товара',x.sku?'Артикул '+x.sku:'',`<div class="detail-title">${itemIcon(x)}<div class="grow"><h2>${esc(x.name)}</h2><p>${esc(x.category||'Без категории')}${x.barcode?' · '+esc(x.barcode):''}</p></div></div><div class="detail-total"><div><small>Всего на складе</small><br><b>${q(itemTotal(x,''))} ${esc(x.unit)}</b></div>${badge(x)}</div><h3>По местам хранения</h3>${rows.map(({p,n})=>`<div class="kv-row"><span>${esc(p.name)}</span><span class="strong mono">${q(n)} ${esc(x.unit)}</span></div>`).join('')}<div style="margin-top:20px"><div class="kv-row"><span>Минимальный запас</span><span>${q(x.min)} ${esc(x.unit)}</span></div><div class="kv-row"><span>Справочная цена за ${esc(x.unit)}</span><span>${money(x.price)}</span></div>${Object.entries(x.fields||{}).map(([k,v])=>`<div class="kv-row"><span>${esc(k)}</span><span>${esc(v)}</span></div>`).join('')}</div>${x.note?`<div class="notice" style="margin-top:18px;white-space:pre-wrap">${esc(x.note)}</div>`:''}<div class="row wrap" style="margin-top:20px"><button class="btn small" data-action="label-item" data-id="${x.id}">${ic('barcode')}QR-этикетка</button><button class="btn small" data-action="edit-item" data-id="${x.id}" ${disabledWrite()}>${ic('edit')}Изменить</button><button class="btn small" data-action="archive-item" data-id="${x.id}" ${disabledWrite()}>${ic('archive')}${x.archived?'Вернуть из архива':'В архив'}</button></div>`,x.archived?'':`<button class="btn" data-action="operation" data-kind="out" data-id="${x.id}" ${disabledWrite()}>${ic('out')}Расход</button><button class="btn primary" data-action="operation" data-kind="in" data-id="${x.id}" ${disabledWrite()}>${ic('in')}Приход</button>`);}
function reverseModal(eventID){const e=state.events.find(x=>x.id===eventID);if(!e)return;modal('Отменить движение','Исходная запись останется. Появится обратное движение.',`<form id="reverse-form" class="stack"><div class="notice">${esc(names[e.kind])} · ${esc(state.items[e.item]?.name)} · ${esc(niceDate(e.at,true))}</div><label class="field">Причина отмены<textarea name="note" required maxlength="1000" placeholder="Например, ошибочное количество"></textarea></label><div class="notice warn">Отмена прихода может быть невозможна, если этот товар уже израсходован или перемещён.</div></form>`,formButtons('reverse-form','Провести отмену'));$('#reverse-form').addEventListener('submit',ev=>{ev.preventDefault();const f=ev.currentTarget;runForm(f,async()=>{const c={id:id(),type:'reverse',ref:eventID,note:String(new FormData(f).get('note'))};const r=await send(c);toast(r.saved?'Обратное движение сохранено.':'Отмена ожидает подтверждения.',r.saved?'':'warn');});});}
function accountModal(mode='login',defaults={}){
 const server=defaults.server||cfg.server||inferServer();
 modal(mode==='setup'?'Создать общий склад':'Подключить общий склад','Локальные данные сохранятся отдельно. Общий склад работает через сервер.',`${mode!=='setup'?`<div class="form-tabs"><button data-action="account-tab" data-kind="login" class="${mode==='login'?'active':''}">Уже есть аккаунт</button><button data-action="account-tab" data-kind="join" class="${mode==='join'?'active':''}">По приглашению</button></div>`:''}<form id="account-form" class="stack"><label class="field">Адрес сервера<input class="input" name="server" required type="text" inputmode="url" spellcheck="false" autocapitalize="none" placeholder="http://192.168.1.20:8787" value="${esc(server)}"><small>Скопируйте адрес из раздела «Участники» на компьютере.</small></label>${mode==='setup'?'<label class="field">Название склада<input class="input" name="space" required maxlength="80" placeholder="Например, Мастерская"></label>':''}${mode==='join'?`<label class="field">Одноразовый код приглашения<input class="input" name="code" required autocapitalize="none" spellcheck="false" value="${esc(defaults.code||'')}" placeholder="Код от владельца"></label>`:''}${mode!=='login'?'<label class="field">Ваше имя<input class="input" name="name" required maxlength="80" placeholder="Как вас увидят коллеги"></label>':''}<label class="field">Логин<input class="input" name="login" required minlength="3" maxlength="80" autocomplete="username" autocapitalize="none" spellcheck="false" placeholder="Латинские буквы и цифры" value="${esc(cfg.login||'')}"></label><label class="field">${mode==='login'?'Пароль':'Придумайте пароль'}<input class="input" name="password" type="password" required ${mode==='login'?'':'minlength="10"'} maxlength="256" autocomplete="${mode==='login'?'current-password':'new-password'}"><small>При создании аккаунта — не менее 10 символов. Пароль нельзя восстановить через разработчика.</small></label><div class="notice warn">HTTP — только для доверенной локальной сети. Для работы через интернет нужен HTTPS. Телефон должен иметь доступ к этому адресу; выключенный компьютер не синхронизирует данные.</div></form>`,formButtons('account-form',mode==='login'?'Войти':mode==='setup'?'Создать склад':'Присоединиться'));
 $('#account-form').dataset.mode=mode;
 $('#account-form').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget;runForm(f,async()=>{const d=new FormData(f),base=normalizeServer(String(d.get('server')));if(cfg.mode==='remote'&&queue.length)throw new Error('Сначала разберите очередь текущего общего склада.');
 const data={login:String(d.get('login')),password:String(d.get('password'))};if(mode!=='login')data.name=String(d.get('name'));if(mode==='join')data.code=String(d.get('code')).trim();if(mode==='setup'){data.space=String(d.get('space'));data.setup=setupKey;}
 const res=await api('/api/'+mode,data,base,'');cfg={...cfg,mode:'remote',server:base,token:res.token,login:res.state.me.login,demo:false};saveCfg();state=null;queue=await getKV(queueKey())||[];await acceptState(res.state);network='online';page='home';$('#app').innerHTML='';render();toast('Вы подключены к общему складу.');});});
}
